    for r, c in input_ones:
        if c == 0:
            for col in range(1, w):
                if grid[r][col] == 2:
                    result[r][col] = 1
        elif c == w - 1:
            for col in range(w - 2, -1, -1):
                if grid[r][col] == 2:
                    result[r][col] = 1

    # Step 2: Both edge rows fill entire row
    rows_both_edges = set(r for r, _ in input_ones if (r, 0) in input_ones and (r, w-1) in input_ones)
    for r in rows_both_edges:
        for col in range(w):
            result[r][col] = 1

    # Step 3: Vertical fill - fill BETWEEN consecutive 1s (exclusive of endpoints)
    for c in set(cc for _, cc in input_ones):
        one_rows = sorted([r for r in range(h) if grid[r][c] == 1])
        for i in range(len(one_rows) - 1):
            r1, r2 = one_rows[i], one_rows[i+1]
            # Fill rows STRICTLY between r1 and r2 (exclusive)
            for r in range(r1 + 1, r2):
                result[r][c] = 1

    # Step 4: Block detection and fill
    def get_blocks():
        h, w = len(result), len(result[0])
        visited = [[False]*w for _ in range(h)]
        blocks = []
        for r in range(h):
            for col in range(w):
                if result[r][col] == 2 and not visited[r][col]:
                    queue = [(r, col)]
                    visited[r][col] = True
                    block = []
                    while queue:
                        cr, cq = queue.pop(0)
                        block.append((cr, cq))
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cq + dc
                            if 0 <= nr < h and 0 <= nc < w and result[nr][nc] == 2 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                    blocks.append(block)
        return blocks

    blocks = get_blocks()
    for block in blocks:
        if any(result[r][c] == 1 for r, c in block):
            for r, c in block:
