# Verify solver works on saved demos
def solver(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]
    input_ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    for r, c in input_ones:
        if c == 0:
            for col in range(1, w):
                if grid[r][col] == 2:
                    result[r][col] = 1
        elif c == w - 1:
            for col in range(w - 2, -1, -1):
                if grid[r][col] == 2:
                    result[r][col] = 1

    for r, c in input_ones:
        if c == 0 and (r, w-1) in input_ones:
            for col in range(w):
                result[r][col] = 1

    cols_with_ones = set(col for _, col in input_ones)
    for c in cols_with_ones:
        one_rows = sorted([r for r in range(h) if grid[r][c] == 1])
        if len(one_rows) >= 2:
            for i in range(len(one_rows) - 1):
                r1, r2 = one_rows[i], one_rows[i+1]
                for r in range(r1 + 1, r2):
                    result[r][c] = 1

    blocks = []
    visited = [[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and not visited[r][c]:
                block = []
                queue = [(r,c)]
                visited[r][c] = True
                while queue:
                    cr, cq = queue.pop(0)
                    block.append((cr, cq))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cq+dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                blocks.append(block)

    for block in blocks:
        has_1 = any(result[r][c] == 1 for r, c in block)
        if has_1:
            for rr, cc in block:
                result[rr][cc] = 1
    return result

